BEGIN;
CREATE TABLE printful_fulfillment_events(id uuid PRIMARY KEY,payload_digest text NOT NULL UNIQUE,event_type text NOT NULL,store_id text NOT NULL,occurred_at timestamptz NOT NULL,payload jsonb NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fulfillment_shipments(id uuid PRIMARY KEY,commerce_order_id uuid NOT NULL REFERENCES commerce_orders(id) ON DELETE RESTRICT,printful_shipment_id text NOT NULL UNIQUE,carrier text,shipment_status text NOT NULL,tracking_number text,tracking_url text,shipped_at timestamptz,raw_snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fulfillment_shipment_items(id uuid PRIMARY KEY,shipment_id uuid NOT NULL REFERENCES fulfillment_shipments(id) ON DELETE CASCADE,shopify_line_item_id text NOT NULL,quantity integer NOT NULL CHECK(quantity>0),UNIQUE(shipment_id,shopify_line_item_id));
CREATE TABLE shopify_fulfillment_jobs(id uuid PRIMARY KEY,shipment_id uuid NOT NULL UNIQUE REFERENCES fulfillment_shipments(id) ON DELETE RESTRICT,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','RUNNING','SUCCEEDED','FAILED')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),available_at timestamptz NOT NULL DEFAULT now(),locked_by text,lease_expires_at timestamptz,request_payload jsonb,response_payload jsonb,shopify_fulfillment_id text,last_error text,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,CHECK((status='RUNNING' AND locked_by IS NOT NULL AND lease_expires_at IS NOT NULL)OR(status<>'RUNNING' AND locked_by IS NULL AND lease_expires_at IS NULL)));
CREATE INDEX shopify_fulfillment_jobs_ready ON shopify_fulfillment_jobs(available_at,created_at) WHERE status='PENDING';
COMMIT;
